#include <iostream>

void runGame(int target) {
    std::cout << "I have a number between 1 and 1000.\n";
    std::cout << "Can you guess my number?\n";
    std::cout << "Please type your first guess.\n";

    int guess = 0;
    while (std::cout << "? " && std::cin >> guess) {
        if (guess == target) {
            std::cout << "\nExcellent! You guessed the number!\n";
            break;
        } else if (guess > target) {
            std::cout << "Too high. Try again.\n";
        } else {
            std::cout << "Too low. Try again.\n";
        }
    }
}

int main() {
    // Target value matching Fig 1.17 - Fig 1.19 (384)
    const int targetNumber = 384;

    runGame(targetNumber);

    std::cout << "Would you like to play again?\n";
    std::cout << "Please type ( 1=yes, 2=no )? ";
    int choice = 0;
    if (std::cin >> choice) {
        // User selects 2 to terminate
        if (choice == 2) {
            // Exit application gracefully
        }
    }

    return 0;
}
